theorem confluent_normalForm_unique {r : α → α → Prop} (hC : Confluent r) {a n₁ n₂ : α}
    (h₁ : Relation.ReflTransGen r a n₁) (hn₁ : NormalForm r n₁)
    (h₂ : Relation.ReflTransGen r a n₂) (hn₂ : NormalForm r n₂) : n₁ = n₂

theorem D1_compile_ignores_constraint_name (n1 n2 : VarName) (a b : VarName) :
    compile_constraint [] { name := n1, kind := .distance, args := [a, b] } =
    compile_constraint [] { name := n2, kind := .distance, args := [a, b] }
